static async Task<int[]> SortAsync(int[] data) {
    if (data.Length < 1024) return Sequential(data);          // base case
    var mid = data.Length / 2;
    var left  = Task.Run(() => SortAsync(data[..mid]));
    var right = Task.Run(() => SortAsync(data[mid..]));
    return Merge(await left, await right);                    // join + combine
}
